test('a source import saved by a newer release refuses the cover change with a reload request and no retry', async () => {
  const source=detail();source.assets=[{slotId:'cover',state:'ready',byteLength:3,sha256:'a'.repeat(64),contentType:'image/jpeg',tags:null,recovery:{operationId,expectedRevision:1,kind:'upload',startedByMe:true}}];const writes:string[]=[];
  vi.stubGlobal('fetch',vi.fn(async(path:string,init:RequestInit)=>{
    if(init.method==='POST'){writes.push(path);return json({code:'ADMIN_IMPORT_RELOAD_REQUIRED'},409);}
    if(path.endsWith('/cover-operations'))return json({items:[]});
    if(path.includes('/imports?')){const {manifest,draft:_draft,suggestions,decisions:_decisions,capabilities:_capabilities,receipts:_receipts,assets:_assets,published:_published,publicationRecovery:_recovery,selectedCoverSlotId:_selected,coverChoice:_coverChoice,approvalDigest:_digest,valueRevision:_value,automaticPaths:_automatic,lookupPaths:_lookup,possibleLabelEntryKeys:_labels,...common}=source;return json({items:[{...common,title:'Synthetic source',rootLabel:manifest.rootLabel,artistName:'',visibility:'public',pendingSuggestions:suggestions.length}],counts:{all:1,analyzing:0,awaitingReview:1,needsAttention:0,completed:0},nextCursor:null});}
    return json({item:source,receipt:null});
  }));
  const confirmed=mount();await waitFor(()=>expect(screen.getByRole('button',{name:'Choose from import projects'})).toBeEnabled());fireEvent.click(screen.getByRole('button',{name:'Choose from import projects'}));
  fireEvent.click(await screen.findByRole('button',{name:'Synthetic source'}));fireEvent.click(await screen.findByRole('button',{name:/Use this image/}));fireEvent.click(within(screen.getByRole('dialog')).getByRole('button',{name:'Replace catalog cover'}));
  // The refusal precedes admission: only this action offers a reload, and nothing is left to retry.
  expect(await screen.findByText('The administrator workbench was updated. Reload the page to continue; unsaved edits on this page are not kept.')).toBeVisible();
  expect(screen.getByRole('button',{name:'Reload page'})).toBeVisible();expect(screen.queryByRole('button',{name:'Retry original operation'})).not.toBeInTheDocument();
  expect(adminWorkspace.getSnapshot().reloadRequired).toBe(false);expect(confirmed).not.toHaveBeenCalled();expect(writes).toEqual([`/api/admin/v1/catalog/artist/${item.id}/cover`]);
});

/** A file chosen from this computer: synthetic signature bytes only, read through its own arrayBuffer (jsdom has none). */
const png=[0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a,0,0,0,13,0x49,0x48,0x44,0x52,1,2,3],gif=[0x47,0x49,0x46,0x38,0x39,0x61,1,0,1,0,0,0],uploadId='b'.repeat(24);
function chosen(bytes:number[],name='cover.png'){const file=new File([Uint8Array.from(bytes)],name),read=vi.fn(async()=>Uint8Array.from(bytes).buffer);Object.defineProperty(file,'arrayBuffer',{value:read});return {file,read};}
const pick=(file:File)=>fireEvent.change(document.querySelector('input[type=file]')!,{target:{files:[file]}});
const readBytes=(blob:Blob)=>new Promise<number[]>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve([...new Uint8Array(reader.result as ArrayBuffer)]);reader.onerror=reject;reader.readAsArrayBuffer(blob);});
const keyOf=(init:RequestInit)=>new Headers(init.headers).get('Idempotency-Key');
type Sent={path:string;init:RequestInit};
/** Answers uploads through `reply`, cover approvals and removals as confirmed, and every read with an empty operation list. */
function serveUploads(reply:(sent:Sent,index:number)=>Response|Promise<Response>=sent=>staged(sent),items:unknown[]=[]){
  const uploads:Sent[]=[],covers:Sent[]=[];
  vi.stubGlobal('fetch',vi.fn(async(path:string,init:RequestInit={})=>{
    if(path.endsWith('/cover-uploads')){const sent={path,init};uploads.push(sent);return reply(sent,uploads.length-1);}
    if(init.method==='POST'||init.method==='DELETE'){covers.push({path,init});return json({item,receipt:{operationId:JSON.parse(String(init.body)).operationId},coverOperation:{state:'complete',cleanupPending:false}});}
    return json({items});
  }));
  return {uploads,covers};
}
const staged=(sent:Sent,id=uploadId)=>json({upload:{id},receipt:{operationId:keyOf(sent.init)}});
const previews=()=>{let count=0;return {created:vi.spyOn(URL,'createObjectURL').mockImplementation(()=>`blob:synthetic-preview-${++count}`),revoked:vi.spyOn(URL,'revokeObjectURL').mockImplementation(()=>undefined)};};
const uploadButton=()=>screen.getByRole('button',{name:'Upload from this computer'});
const ready=()=>waitFor(()=>expect(uploadButton()).toBeEnabled());

test('the upload button sits beside Choose and is disabled offline, without editing, with an unresolved operation and while an upload runs', async () => {
  serveUploads();mount();await ready();
  expect(screen.getByRole('button',{name:'Choose from import projects'}).nextElementSibling).toBe(uploadButton());cleanup();
  vi.stubGlobal('navigator',{...navigator,onLine:false});mount();expect(uploadButton()).toBeDisabled();cleanup();vi.unstubAllGlobals();
  serveUploads();mount(vi.fn(),{...item,capabilities:{editing:false,visibility:true}});await waitFor(()=>expect(screen.getByRole('button',{name:'Refresh status'})).toBeEnabled());expect(uploadButton()).toBeDisabled();cleanup();
  serveUploads(undefined,[{operationId,startedByMe:true,state:'needsAttention',cleanupPending:false}]);mount();await screen.findByRole('button',{name:'Resume operation'});expect(uploadButton()).toBeDisabled();cleanup();
  const source=detail();source.assets=[{slotId:'cover',state:'ready',byteLength:3,sha256:'a'.repeat(64),contentType:'image/jpeg',tags:null,recovery:{operationId,expectedRevision:1,kind:'upload',startedByMe:true}}];
  let release!:(response:Response)=>void;const uploads:string[]=[];
  vi.stubGlobal('fetch',vi.fn(async(path:string)=>{
    if(path.endsWith('/cover-uploads')){uploads.push(path);return new Promise<Response>(resolve=>{release=resolve;});}
    if(path.endsWith('/cover-operations'))return json({items:[]});
    if(path.includes('/imports?')){const {manifest,draft:_draft,suggestions,decisions:_decisions,capabilities:_capabilities,receipts:_receipts,assets:_assets,published:_published,publicationRecovery:_recovery,selectedCoverSlotId:_selected,coverChoice:_coverChoice,approvalDigest:_digest,valueRevision:_value,automaticPaths:_automatic,lookupPaths:_lookup,possibleLabelEntryKeys:_labels,...common}=source;return json({items:[{...common,title:'Synthetic source',rootLabel:manifest.rootLabel,artistName:'',visibility:'hidden',pendingSuggestions:suggestions.length}],counts:{all:1,analyzing:0,awaitingReview:1,needsAttention:0,completed:0},nextCursor:null});}
    return json({item:source,receipt:null});
  }));
  mount();await ready();fireEvent.click(screen.getByRole('button',{name:'Choose from import projects'}));fireEvent.click(await screen.findByRole('button',{name:'Synthetic source'}));
  const candidate=await screen.findByRole('button',{name:/Use this image/});expect(candidate).toBeEnabled();
  pick(chosen(png).file);await waitFor(()=>expect(uploads).toHaveLength(1));
  expect(screen.getByRole('status')).toHaveTextContent('Uploading the image…');
  for(const name of ['Upload from this computer','Choose from import projects','Remove catalog cover'])expect(screen.getByRole('button',{name})).toBeDisabled();
  expect(candidate).toBeDisabled();
  release(json({code:'ADMIN_CATALOG_COVER_INVALID_IMAGE'},400));expect(await screen.findByText('This image could not be used. Use a complete, still JPG, PNG or WebP image of at most 16 megapixels.')).toBeVisible();
  await ready();expect(candidate).toBeEnabled();
});

