test('an upload opens the existing confirmation with a proportional preview; Cancel sends nothing and a new choice is a new intent; confirm sends the upload', async () => {
  const {uploads,covers}=serveUploads(),{created,revoked}=previews(),{file}=chosen(png);mount();await ready();
  pick(file);const dialog=await screen.findByRole('dialog');
  expect(uploads[0].path).toBe(`/api/admin/v1/catalog/artist/${item.id}/cover-uploads`);expect(uploads[0].init.method).toBe('POST');
  expect(await readBytes(uploads[0].init.body as Blob)).toEqual(expect.arrayContaining(png));
  expect(within(dialog).getByText('Synthetic artist')).toBeVisible();expect(dialog).not.toHaveTextContent(/metadata/i);
  const preview=within(dialog).getByRole('img',{name:'Image to upload'});expect(preview).toHaveAttribute('src','blob:synthetic-preview-1');
  Object.defineProperty(preview,'naturalWidth',{value:200});Object.defineProperty(preview,'naturalHeight',{value:100});fireEvent.load(preview);
  expect(preview).toHaveAttribute('width','96');expect(preview).toHaveAttribute('height','48');
  await waitFor(()=>expect(within(dialog).getByRole('button',{name:'Cancel'})).toHaveFocus());
  fireEvent.click(within(dialog).getByRole('button',{name:'Cancel'}));expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  expect(revoked).toHaveBeenCalledWith('blob:synthetic-preview-1');expect(covers).toHaveLength(0);
  pick(file);const second=await screen.findByRole('dialog');expect(uploads).toHaveLength(2);expect(keyOf(uploads[1].init)).not.toBe(keyOf(uploads[0].init));expect(created).toHaveBeenCalledTimes(2);
  fireEvent.click(within(second).getByRole('button',{name:'Replace catalog cover'}));
  expect(await screen.findByText('The catalog cover change is confirmed.')).toBeVisible();
  expect(covers).toHaveLength(1);expect(covers[0].path).toBe(`/api/admin/v1/catalog/artist/${item.id}/cover`);
  const body=JSON.parse(String(covers[0].init.body));expect(Object.keys(body).sort()).toEqual(['expectedRevision','operationId','uploadId']);
  expect(body).toMatchObject({expectedRevision:item.revision,uploadId});expect(revoked).toHaveBeenCalledWith('blob:synthetic-preview-2');
});

