test('an unknown outcome keeps the intent: Retry resends the same key and bytes after the file becomes unreadable, an unconfirmed receipt keeps it, and Cancel forgets it', async () => {
  const {uploads}=serveUploads((sent,index)=>{if(index===0)throw new TypeError('offline');return index===1?json({upload:{id:uploadId},receipt:{operationId:'40000000-0000-4000-8000-000000000004'}}):staged(sent);});
  const {file,read}=chosen(png);mount();await ready();pick(file);
  expect(await screen.findByText('The upload did not finish. Retry it, or cancel and choose the image again.')).toBeVisible();
  // A kept upload locks every new approval until it is retried or cancelled.
  for(const name of ['Upload from this computer','Choose from import projects','Remove catalog cover'])expect(screen.getByRole('button',{name})).toBeDisabled();
  read.mockRejectedValue(new DOMException('moved','NotReadableError'));
  fireEvent.click(screen.getByRole('button',{name:'Retry original operation'}));await waitFor(()=>expect(uploads).toHaveLength(2));
  expect(keyOf(uploads[1].init)).toBe(keyOf(uploads[0].init));expect(await readBytes(uploads[1].init.body as Blob)).toEqual(await readBytes(uploads[0].init.body as Blob));
  expect(await screen.findByRole('button',{name:'Retry original operation'})).toBeEnabled();expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  fireEvent.click(screen.getByRole('button',{name:'Cancel'}));expect(screen.queryByRole('button',{name:'Retry original operation'})).not.toBeInTheDocument();
  await ready();expect(uploads).toHaveLength(2);expect(read).toHaveBeenCalledOnce();
});

test.each([
  [409,'ADMIN_CATALOG_COVER_SOURCE_CHANGED','This project changed elsewhere. Refresh its saved version and compare your changes before trying again.',false],
  [409,'ADMIN_CATALOG_IDEMPOTENCY_CONFLICT','This project changed elsewhere. Refresh its saved version and compare your changes before trying again.',false],
  [429,'ADMIN_CATALOG_COVER_UPLOAD_LIMIT','Too many uploaded images are still unused. Unused images are removed a day after upload; try again later.',false],
  [429,undefined,'Another upload is in progress. Try again in a moment.',true],
  [413,'ADMIN_CATALOG_COVER_TOO_LARGE','This image is larger than the cover upload limit, or becomes larger once it is re-saved without its metadata.',false],
  [503,'ADMIN_IMPORT_STORAGE_UNAVAILABLE','Uploading a cover is not available on this server.',false],
  [503,'ADMIN_CATALOG_COVER_UNKNOWN','The upload did not finish. Retry it, or cancel and choose the image again.',true]
] as const)('a %i %s refusal shows its message and offers Retry only for an unknown outcome or a busy server', async (status,code,message,retry) => {
  serveUploads(()=>json(code?{code}:{message:'Too many concurrent requests.'},status));mount();await ready();pick(chosen(png).file);
  expect(await screen.findByText(message)).toBeVisible();
  expect(Boolean(screen.queryByRole('button',{name:'Retry original operation'}))).toBe(retry);expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
});

test.each(['reset','role','view'] as const)('after an unknown outcome a %s change removes Retry, sends nothing more and closes an open upload approval', async change => {
  const {uploads}=serveUploads((sent,index)=>{if(index===0)throw new TypeError('offline');return staged(sent);}),{revoked}=previews();mount();await ready();
  const authorize=()=>adminWorkspace.authorize(captureAccountOperation(viewer),true,true,undefined,{editing:true,visibility:true});
  const leave=()=>act(()=>{if(change==='reset'){adminWorkspace.reset();authorize();}else if(change==='role'){adminWorkspace.suspend();authorize();}else adminWorkspace.select('user');adminWorkspace.select('admin');});
  pick(chosen(png).file);await screen.findByRole('button',{name:'Retry original operation'});
  leave();await ready();expect(screen.queryByRole('button',{name:'Retry original operation'})).not.toBeInTheDocument();expect(uploads).toHaveLength(1);
  pick(chosen(png).file);await screen.findByRole('dialog');expect(uploads).toHaveLength(2);
  leave();await waitFor(()=>expect(screen.queryByRole('dialog')).not.toBeInTheDocument());expect(revoked).toHaveBeenCalledWith('blob:synthetic-preview-1');expect(uploads).toHaveLength(2);
});

test('a successful upload answered after leaving Admin view opens no confirmation', async () => {
  let release!:(response:Response)=>void;const pending=new Promise<Response>(resolve=>{release=resolve;});
  const {uploads}=serveUploads(()=>pending),{created}=previews();mount();await ready();pick(chosen(png).file);await waitFor(()=>expect(uploads).toHaveLength(1));
  act(()=>adminWorkspace.select('user'));release(staged(uploads[0]));
  act(()=>adminWorkspace.select('admin'));await ready();
  expect(screen.queryByRole('dialog')).not.toBeInTheDocument();expect(created).not.toHaveBeenCalled();expect(screen.queryByRole('status')).not.toBeInTheDocument();
});

