/** Mounts the panel beside another page dialog, as the Album hero's confirmations are; the returned function opens or closes it. */
function besideDialog(){
  const client=new QueryClient(),focus={current:null};client.setQueryData(['browser-session'],session);
  const view=(open:boolean)=><QueryClientProvider client={client}><MemoryRouter>{open&&<ModalDialog title="Synthetic page confirmation" initialFocusRef={focus} onClose={()=>undefined}><p>Synthetic</p></ModalDialog>}<CatalogCover item={item} kind={item.kind} id={item.id} disabled={false} onConfirmed={vi.fn()} onRemoved={vi.fn()}/></MemoryRouter></QueryClientProvider>;
  const {rerender}=render(view(true));return (open:boolean)=>rerender(view(open));
}

