test('Use this image opens the waiting upload\'s confirmation with its preview, whose Cancel returns focus to the upload button, and confirming it sends that upload', async () => {
  const {uploads,covers}=serveUploads(),{created,revoked}=previews(),show=besideDialog();await ready();
  pick(chosen(png).file);let use=await screen.findByRole('button',{name:'Use this image'});
  show(false);expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  fireEvent.click(use);let dialog=await screen.findByRole('dialog');
  expect(within(dialog).getByRole('img',{name:'Image to upload'})).toHaveAttribute('src','blob:synthetic-preview-1');expect(created).toHaveBeenCalledOnce();
  expect(screen.queryByRole('button',{name:'Use this image'})).not.toBeInTheDocument();
  fireEvent.click(within(dialog).getByRole('button',{name:'Cancel'}));expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  expect(uploadButton()).toHaveFocus();expect(revoked).toHaveBeenCalledWith('blob:synthetic-preview-1');expect(covers).toHaveLength(0);
  show(true);pick(chosen(png).file);use=await screen.findByRole('button',{name:'Use this image'});show(false);
  fireEvent.click(use);dialog=await screen.findByRole('dialog');expect(within(dialog).getByRole('img',{name:'Image to upload'})).toHaveAttribute('src','blob:synthetic-preview-2');
  fireEvent.click(within(dialog).getByRole('button',{name:'Replace catalog cover'}));
  await waitFor(()=>expect(covers).toHaveLength(1));expect(JSON.parse(String(covers[0].init.body))).toMatchObject({expectedRevision:item.revision,uploadId});
  expect(uploads).toHaveLength(2);expect(revoked).toHaveBeenCalledWith('blob:synthetic-preview-2');
});

